INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7421090, 1171148, 104230, '<td valign="top">At first I was struck by how relatively flat the light was in this image, but having been up in the Rocky mountains early in the morning on the way to go skiing, I realized this very effectively captures the special light and mood of that time of day. The half submerged log/stump covered with a dusting of snow, placed so perfectly, is what makes this image for me. My top vote, along with a few others.</td>', 'At first I was struck by how relatively flat the light was in this image, but having been up in the Rocky mountains early in the morning on the way to go skiing, I realized this very effectively captures the special light and mood of that time of day. The half submerged log/stump covered with a dusting of snow, placed so perfectly, is what makes this image for me. My top vote, along with a few others.', '2015-12-07 23:45:40.000000', NULL, 1),
(7421091, 1171123, 104230, '<td valign="top">Wonderful.  The drops on the branches add a lot too.</td>', 'Wonderful.  The drops on the branches add a lot too.', '2015-12-07 23:46:51.000000', NULL, 1),
